      html += '<div class="lane lane-backlog' +
        (col.id === 'blocked' ? ' lane-blocked' : '') +
        '" style="--accent:' + esc(f.accent) + '">' +
        '<div class="lane-head"><span>' + esc(col.title) + '</span>' +
        '<span class="count">' + list.length + '</span></div>' +
        '<div class="lane-body">' +
