  // would double-count every phase.
  function flowHtml(f, st) {
    var lanes = st.lanes || {};
    var cards = [];
    (CFG.lanes || []).forEach(function (l) {
      (lanes[l.id] || []).forEach(function (c) { if (c) cards.push(c); });
    });
