        '</span>');
    });
    if (s.rework.rounds) {
      chips.push('<span class="flow-chip rw"><b>rework &times;' + s.rework.rounds +
        '</b>' + (s.rework.ms ? ' · &Sigma; ' + esc(fmtDur(s.rework.ms)) : '') +
        '</span>');
