  }).join('');
}

function fail(f, msg) {
  skeleton();                       // clear stale lanes — never keep old data
  errEl.hidden = false;
  errEl.innerHTML = '<span class="err-dot"></span>' + esc(f.name) +
    ': ' + esc(msg) +
