    chips.push('<span class="flow-chip"><b>' + esc(stateTitle(p.state)) +
      '</b> ' + p.cards + ' card' + (p.cards > 1 ? 's' : '') +
      (p.totalMs ? ' · &Sigma; ' + esc(fmtDur(p.totalMs)) +
        ' · avg ' + esc(fmtDur(Math.round(p.totalMs / p.cards))) : '') +
