      }).join(', ') +
      '"><b>&Sigma; ' + esc(fmtK(s.tokens.total)) + ' tok</b> · ' +
      Object.keys(s.tokens.legs).length + ' legs</span>');
  }
  if (s.lead && s.lead.avgMs != null) {
