  // `javascript:`/`data:` value in a snapshot (or ?fixture= json) must fall
  // back to the config-built link — only real http(s) URLs pass through.
  function safeHref(u, fallback) {
    return /^https?:\/\//i.test(u) ? u : fallback;
  }

