  // the run carried no timestamps.
  function ciwaitHtml(c) {
    var s = FLOW.ciSplit(c, nowMs());
    if (!s) return '';
    var bits = [];
    if (s.ciMs != null) bits.push('<b>CI ' + esc(fmtDur(s.ciMs)) + '</b>');
    if (s.queueMs != null) bits.push('wait ' + esc(fmtDur(s.queueMs)));
