/**
 * Unit tests for site/factory/steps.js — the factory board's per-card
 * pipeline stepper (gh-726: dots → labeled stepper, done/current/pending/
 * failed states).
 *
 * Pure functions only — no DOM, no tool globals. The same module ships to
