    }
    var cols = CFG.backlogColumns || [];
    for (var j = 0; j < cols.length; j++) {
      if (cols[j].id === key) return cols[j].title;
    }
    if (key === 'fresh') return 'PR created';
    return key || '—';
  }

  // ── cards ──────────────────────────────────────────────────────────────────
  function keyOf(c, laneId) {
    return (c.pr != null ? 'pr-' + c.pr : 'issue-' + c.issue) + '@' + laneId;
  }

