    ], NOW, false);
    assert.deepEqual(rail.map(function (p) { return p.state; }),
      ['pr_created', 'review', 'approved_queue']);
    assert.equal(rail[0].totalMs, 3600000, '1h in pr_created');
    assert.equal(rail[1].totalMs, 1800000, '30m in review');

