+    assert.equal(flow.ciSplit({ checks: { at: 'not-a-date' } }, 0), null);
+  });
+
+  test('queued run without runStartedAt: everything so far is queue wait', function () {
+    var s = flow.ciSplit({ checks: { verdict: 'queued', at: '2026-10-03T12:00:00Z' } },
