    if (s.queueMs != null) bits.push('wait ' + esc(fmtDur(s.queueMs)));
    return bits.length
      ? '<span class="ciwait" title="CI wall-time vs queue wait — ' +
        'queue wait is runner backlog / mutex, not work">' +
