// ── skeleton + error states ────────────────────────────────────────────────
function skeleton() {
  statusEl.hidden = true;
  errEl.hidden = true;
  backlogEl.innerHTML = '';
  backlogEl.hidden = true;
  flowEl.innerHTML = '';           // v4 strip: no stale factory's numbers
  flowEl.hidden = true;
  lanesEl.innerHTML = CFG.lanes.map(function (l) {
