  var age = enteredAt
    ? '<span class="age" title="in this state since ' +
      esc(clockTime(enteredAt)) + '">' + esc(ago(enteredAt)) + '</span>'
    : '';
  return '<a class="card' + (isIssue ? ' card-issue' : '') +
      '" href="' + esc(href) + '" target="_blank" rel="noopener" ' +
      'data-key="' + esc(keyOf(c, laneId)) + '">' +
