    assert.equal(flow.ciSplit({}, 0), null);
    assert.equal(flow.ciSplit({ checks: {} }, 0), null);
    assert.equal(flow.ciSplit({ checks: { verdict: 'queued' } }, 0), null);
    assert.equal(flow.ciSplit({ checks: { at: 'not-a-date' } }, 0), null);
  });

