  // ── cards ──────────────────────────────────────────────────────────────────
  function keyOf(c, laneId) {
    return (c.pr != null ? 'pr-' + c.pr : 'issue-' + c.issue) + '@' + laneId;
  }

  // badge row shared by cardHtml + drawerHeaderHtml — one styling path, so
  // label tweaks (hot set, blocked class) can never land in one and miss
