    ], NOW);
    assert.equal(s.tokens.total, 12);
    assert.deepEqual(Object.keys(s.tokens.legs), ['__proto__']);
    assert.equal(s.tokens.legs['__proto__'].total, 12, 'both cards accumulate');
  });
